static int switchdev_deferred_enqueue ( struct net_device * dev , const void * data , size_t data_len , switchdev_deferred_func_t * func ) { struct switchdev_deferred_item * dfitem ; if ( ! dfitem ) { return - ENOMEM ; } dfitem -> dev = dev ; dfitem -> func = func ; memcpy ( dfitem -> data , data , data_len ) ; dev_hold ( dev ) ; spin_lock_bh ( & deferred_lock ) ; list_add_tail ( & dfitem -> list , & deferred ) ; spin_unlock_bh ( & deferred_lock ) ; schedule_work ( & deferred_process_work ) ; return 0 ; } 